parameters.functionCode:
const name = $input.first().json.collectionName;
const description = $input.first().json.description;
const tags = $input.first().json.tags || [];
const items = $input.first().json.items || [];
const author = $input.first().json.author || 'unknown';
const timestamp = new Date().toISOString();

const yaml = `name: ${name}
description: |
  ${description}
tags:
${tags.map(t => `  - ${t}`).join('\n')}
author: ${author}
createdAt: ${timestamp}
items:
${items.map(item => `  - path: ${item.path}\n    kind: ${item.kind}\n    title: ${item.title}`).join('\n')}
`;

return { yamlContent: yaml };

