\`\`\`typescript
mcp_awesome-copil_load_collection({ id: '${collectionId}' })
\`\`\`

---
*Generated by Agent Collection Generator Workflow*
`;

return { docContent: markdown };

const collectionId = $input.first().json.collectionId;
const collectionName = $input.first().json.collectionName;
const timestamp = $input.first().json.timestamp;
const itemCount = $input.first().json.itemCount;
const description = $input.first().json.description;

const registryEntry = {
  id: collectionId,
  name: collectionName,
  description: description.substring(0, 100),
  fileName: `${collectionId}.collection.yml`,
  createdAt: timestamp,
  itemCount: itemCount,
  status: 'active',
  source: 'agent-generated'
};

return { registryEntry, collectionId };

